using System.Text.Json;

var json = """{"CustomerId":"c-42"}""";     // the partner forgot Email
var order = JsonSerializer.Deserialize<CreateOrder>(json)
    ?? throw new JsonException("Empty body");

// No warning: Email is a non-nullable string, but it holds null
Console.WriteLine(order.Email.ToLowerInvariant()); // NullReferenceException

public record CreateOrder(string CustomerId, string Email);

using System.Text.Json;

var options = new JsonSerializerOptions
{
    RespectNullableAnnotations = true,           // "Email": null throws
    RespectRequiredConstructorParameters = true, // a missing Email throws
};

var json = """{"CustomerId":"c-42"}""";
try
{
    JsonSerializer.Deserialize<CreateOrder>(json, options);
}
catch (JsonException)
{
    Console.WriteLine("400 Bad Request: Email is required"); // fails early
}

public record CreateOrder(string CustomerId, string Email);

